class HIVE_OT_proximity(bpy.types.Operator):
    bl_idname = "hive.proximity"
    bl_label = "Proximity Controls"
    bl_description = "Hide the controls far from the mouse and fade them in as it comes near"

    def invoke(self, context, event):
        rig = find_rig(context)
        if rig is None or not rig.get("hive_anim"):
            context.window_manager.hive_proximity = False
            self.report({"WARNING"}, "No Hive rig to show controls of")
            return {"CANCELLED"}
        stop_proximity()
        _proximity.update(rig=rig.name, fades={})
        _proximity["handler"] = bpy.types.SpaceView3D.draw_handler_add(draw_proximity, (), "WINDOW", "POST_VIEW")
        context.window_manager.modal_handler_add(self)
        return {"RUNNING_MODAL"}

    def modal(self, context, event):
        wm = context.window_manager
        rig = bpy.data.objects.get(_proximity["rig"] or "")
        if not wm.hive_proximity or rig is None:
            stop_proximity()
            return {"CANCELLED"}
        if event.type == "MOUSEMOVE":
            from bpy_extras.view3d_utils import location_3d_to_region_2d
            for area in context.window.screen.areas:
                if area.type != "VIEW_3D":
                    continue
                region = next((r for r in area.regions if r.type == "WINDOW"), None)
                if region is None or not (region.x <= event.mouse_x < region.x + region.width
                                          and region.y <= event.mouse_y < region.y + region.height):
                    continue
                rv3d = area.spaces.active.region_3d
                mouse = (event.mouse_x - region.x, event.mouse_y - region.y)
                _proximity["fades"] = proximity_fades(
                    rig, lambda p: location_3d_to_region_2d(region, rv3d, p), mouse)
                apply_proximity(rig, _proximity["fades"])
                area.tag_redraw()
        return {"PASS_THROUGH"}


class HIVE_PT_panel(bpy.types.Panel):
    bl_label = "Hive Rig"
    bl_space_type = "VIEW_3D"
    bl_region_type = "UI"
    bl_category = "Hive"

    def draw(self, context):
        layout = self.layout
        rig = find_rig(context)
        if rig is None:
            layout.label(text="No Hive rig in this file")
            return
        layout.label(text=rig["hive_name"])
        editing = bool(guide_objects(rig))
        col = layout.column(align=True)
        col.operator("hive.edit_guides", icon="EMPTY_DATA")
        sub = col.column(align=True)
        sub.enabled = editing
        sub.operator("hive.mirror_guides", icon="MOD_MIRROR")
        col = layout.column(align=True)
        col.label(text="Components")
        col.operator("hive.add_component", text="Add Fingers").preset = "fingers"
        col.operator("hive.add_component", text="Add Tail").preset = "tail"
        col.operator("hive.remove_component", icon="X")
        layout.operator("hive.rebuild", icon="FILE_REFRESH").keep_weights = True
        box = layout.box()
        box.label(text="Skin and Shapes")
        row = box.row(align=True)
        op = row.operator("hive.send_edits", text="Send All", icon="EXPORT")
        op.weights, op.shapes = True, True
        op = row.operator("hive.send_edits", text="Weights")
        op.weights, op.shapes = True, False
        op = row.operator("hive.send_edits", text="Shapes")
        op.weights, op.shapes = False, True
        sliders = [k for k in rig.keys() if k.startswith("hive_shape_")]
        for k in sorted(sliders):
            box.prop(rig, '["%s"]' % k, text=k[len("hive_shape_"):], slider=True)
        if editing or not rig.get("hive_anim"):
            return

        data = anim_data(rig)
        box = layout.box()
        box.label(text="Animation")
        pose = rig.pose.bones
        whole_range = bool(rig.get("hive_match_range", False))
        if "hive_match_range" in rig.keys():
            box.prop(rig, '["hive_match_range"]', text="Match the whole frame range")
        for limb in data["limbs"]:
            row = box.row(align=True)
            ik_on = pose[limb["ik"]].get("ikfk", 1.0) <= 0.5
            row.label(text="%s (%s)" % (limb["name"], "IK" if ik_on else "FK"))
            op = row.operator("hive.match_limb", text="IK to FK")
            op.limb, op.to, op.whole_range = limb["name"], "fk", whole_range
            op = row.operator("hive.match_limb", text="FK to IK")
            op.limb, op.to, op.whole_range = limb["name"], "ik", whole_range
            # Zoo Hive's switch, blended by hand (0 = IK, 1 = FK), without matching.
            box.prop(pose[limb["ik"]], '["ikfk"]', text="%s ikfk" % limb["name"], slider=True)
        row = box.row(align=True)
        row.operator("hive.mirror_pose", text="Mirror L to R", icon="MOD_MIRROR").source = "left"
        row.operator("hive.mirror_pose", text="Mirror R to L").source = "right"
        box.operator("hive.flip_pose", icon="ARROW_LEFTRIGHT")
        row = box.row(align=True)
        row.operator("hive.reset_pose", text="Reset All", icon="LOOP_BACK").selected = False
        row.operator("hive.reset_pose", text="Reset Selected").selected = True
        box.operator("hive.select_controls", icon="RESTRICT_SELECT_OFF")
        wm = getattr(context, "window_manager", None)
        if wm is not None and hasattr(wm, "hive_proximity"):
            box.prop(wm, "hive_proximity", text="Proximity Controls", icon="HIDE_OFF")
        active = context.active_pose_bone
        if active is not None and active.id_data == rig and active.name in data["spaces"]:
            col = box.column(align=True)
            col.label(text="Space of %s (no pop)" % active.name)
            for i, space in enumerate(data["spaces"][active.name]):
                op = col.operator("hive.switch_space", text=space, depress=int(active.get("space", 0)) == i)
                op.control, op.index = active.name, i
        box = layout.box()
        box.label(text="Pose Library")
        for name in sorted(pose_library(rig)):
            row = box.row(align=True)
            op = row.operator("hive.apply_pose", text=name)
            op.name, op.mirrored = name, False
            op = row.operator("hive.apply_pose", text="", icon="MOD_MIRROR")
            op.name, op.mirrored = name, True
            row.operator("hive.delete_pose", text="", icon="X").name = name
        box.operator("hive.save_pose", icon="ADD")


CLASSES = (
    HIVE_OT_edit_guides,
    HIVE_OT_mirror_guides,
    HIVE_OT_add_component,
    HIVE_OT_remove_component,
    HIVE_OT_rebuild,
    HIVE_OT_send_edits,
    HIVE_OT_match_limb,
    HIVE_OT_mirror_pose,
    HIVE_OT_flip_pose,
    HIVE_OT_save_pose,
    HIVE_OT_apply_pose,
    HIVE_OT_delete_pose,
    HIVE_OT_reset_pose,
    HIVE_OT_select_controls,
    HIVE_OT_switch_space,
    HIVE_OT_proximity,
    HIVE_PT_panel,
)


def register():
    for cls in CLASSES:
        if hasattr(bpy.types, cls.__name__):
            bpy.utils.unregister_class(getattr(bpy.types, cls.__name__))
        bpy.utils.register_class(cls)
    bpy.types.WindowManager.hive_proximity = bpy.props.BoolProperty(
        name="Proximity Controls", default=False, update=toggle_proximity,
        description="Hide the controls far from the mouse in the 3D view and fade them in as it comes near")


def main():
    existing = bpy.data.objects.get(RIG_DATA["name"] + "_rig")
    if existing is not None and existing.get("hive_guides"):
        print("hive-rig: %s is already in this file; the Hive tab is ready" % RIG_DATA["name"])
    else:
        rig, _ = build(RIG_DATA)
        # The pose posed in the hive-rig app, if any, in the pose library.
        if add_studio_pose(rig, RIG_DATA):
            print("hive-rig: the pose from the hive-rig app is in the pose library as Studio pose")
    register()

    # Optional: `-- --save path.blend` when run headless.
    if "--" in sys.argv:
        args = sys.argv[sys.argv.index("--") + 1 :]
        if "--save" in args:
            bpy.ops.wm.save_as_mainfile(filepath=args[args.index("--save") + 1])


if __name__ == "__main__":
    main()
